package builds

import (
	"time"

	"github.com/brendatamaar/yggdrasil/internal/core"
)

// Input is one event for Step. It is a closed set. Every input carries Now;
// IDs are generated by the shell.
type Input interface{ isInput() }

// Enqueue asks for a new build (from the UI, a preset run or an agent).
type Enqueue struct {
	ID    core.BuildID
	Spec  Spec
	Actor Actor
	Now   time.Time
}

// Admit is sent by the queue worker after Next picked this build.
type Admit struct{ Now time.Time }

// StepExited: the step's process ended.
type StepExited struct {
	Index        int
	Attempt      int
	ExitCode     int
	LogTruncated bool
	Now          time.Time
}

// StepStartFailed: the step's process could not start.
type StepStartFailed struct {
	Index   int
	Attempt int
	Reason  StartFailure
	Now     time.Time
}

// Cancel is the user's cancel.
type Cancel struct {
	Actor Actor
	Now   time.Time
}

// ProcessLost is fed at startup for builds found Running or Cancelling: the
// job object killed their processes with ygg.
type ProcessLost struct{ Now time.Time }

// ArtifactsCollected is the result of CollectArtifacts.
type ArtifactsCollected struct {
	Artifacts []Artifact
	Now       time.Time
}

func (Enqueue) isInput()            {}
func (Admit) isInput()              {}
func (StepExited) isInput()         {}
func (StepStartFailed) isInput()    {}
func (Cancel) isInput()             {}
func (ProcessLost) isInput()        {}
func (ArtifactsCollected) isInput() {}
